-- Help search (O373, client/MANIFEST.md): one window where the player types a question or a few words and gets the best
-- answers from the "How it works" cards, the unlock entries of the top menu and the Codex. Offline: no opcode, no AI.
-- The ranking is helpcore.lua; the first steps (shown before the player types), the level, menu path and extra words of
-- each card are helpsearch_data.lua, generated by server/tools/gen_guide_data.lua (the website's beginner guide comes
-- from the same run). A click opens the answer: a card through modules.game_howitworks.show(key), a Codex entry through
-- modules.game_codex.open(id) (the Codex loads on first use), an unlock entry without a card runs its top menu entry.
-- Menu: System > Help Search, hotkey Alt+F (F1 is a hotkey slot of the action bar). API (modules.game_helpsearch):
--   show() / hide() / toggle()   the window
--   search(text)                 fill the box and the list (also for checks)
--   results()                    the shown rows: {{kind, key, title, snippet, where}} (for checks)

local H = HelpCore
local window
local index
local shown = {}
local searchEvent
local menuAdded = false

local function lang()
  local l = rawget(_G, 'ChaosLocale')
  return l and l.get and l.get() or 'en'
end

-- the data is UTF-8 (pt texts, a few English names); the client's fonts draw cp1252
local function convert(s)
  local core = rawget(_G, 'ChaosLocaleCore')
  return core and core.toCp1252 and core.toCp1252(s) or s
end

local function alive(w)
  if not w then return false end
  local ok, destroyed = pcall(function() return w:isDestroyed() end)
  return ok and not destroyed
end

local function moduleTable(name)
  local m = type(modules) == 'table' and modules[name]
  return type(m) == 'table' and m or nil
end

-- the How it works data (the module's HowData, else its file), the Codex data (the module loads on first use)
local function howData()
  local m = moduleTable('game_howitworks')
  local d = m and rawget(m, 'HowData')
  if type(d) == 'table' then return d end
  local ok, res = pcall(dofile, '/modules/game_howitworks/howitworks_data.lua')
  return ok and type(res) == 'table' and res or rawget(_G, 'HowData')
end

local function codexData()
  if not moduleTable('game_codex') and rawget(_G, 'g_modules') and g_modules.ensureModuleLoaded then
    pcall(g_modules.ensureModuleLoaded, 'game_codex')
  end
  local m = moduleTable('game_codex')
  if m and m.getData then
    local ok, d = pcall(m.getData)
    if ok and type(d) == 'table' then return d end
  end
  return rawget(_G, 'CodexData')
end

local function ensureIndex()
  if not index then index = H.buildIndex(howData(), HelpSearchData, codexData()) end
  return index
end

-- ---------------------------------------------------------------- the rows
-- tr() gives cp1252 already (client_chaos_locale); only the data parts are converted
local function whereText(doc)
  if doc.kind == 'codex' then return tr('Codex') .. (doc.tab and (': ' .. convert(doc.tab)) or '') end
  local parts = {}
  if doc.level then parts[#parts + 1] = tr('Level %d+', doc.level) end
  if doc.menu then parts[#parts + 1] = convert(doc.menu) end
  return table.concat(parts, '  |  ')
end

local function open(row)
  if row.kind == 'card' then
    local m = moduleTable('game_howitworks')
    if m and m.show then pcall(m.show, row.key) end
  elseif row.kind == 'codex' then
    local m = moduleTable('game_codex')
    if not m and rawget(_G, 'g_modules') and g_modules.ensureModuleLoaded then
      pcall(g_modules.ensureModuleLoaded, 'game_codex')
      m = moduleTable('game_codex')
    end
    if m and m.open then pcall(m.open, row.key) end
  elseif row.kind == 'unlock' then
    local top = moduleTable('client_chaos_topbar')
    local api = top and top.ChaosTopBar
    if api and api.run and row.menu then pcall(api.run, row.menu) end
  end
end

local function addHeading(list, text)
  local head = g_ui.createWidget('HelpHeading', list)
  head:setText(text)
  return head
end

local function addRow(list, row)
  local w = g_ui.createWidget('HelpResult', list)
  w:getChildById('title'):setText(row.title)
  w:getChildById('where'):setText(row.where)
  w:getChildById('snippet'):setText(row.snippet)
  w:setTooltip(row.tooltip or row.snippet)
  w.onClick = function() open(row) end
  return w
end

local function rowOf(doc, snippet)
  local l = lang()
  return { kind = doc.kind, key = doc.key, menu = doc.menu, title = convert(H.pick(doc.title, l)),
    snippet = convert(snippet), where = whereText(doc) }
end

local function draw(text)
  if not alive(window) then return end
  local list = window:getChildById('list')
  list:destroyChildren()
  shown = {}
  local ix = ensureIndex()
  local l = lang()
  if H.tokens(text)[1] == nil then
    addHeading(list, tr('First steps'))
    if HelpSearchData and HelpSearchData.intro then addHeading(list, convert(H.pick(HelpSearchData.intro, l))) end
    for _, s in ipairs(H.firstSteps(ix, HelpSearchData)) do
      local row = rowOf(s.doc, H.shorten(H.pick(s.tip, l)))
      shown[#shown + 1] = row
      addRow(list, row)
    end
    return
  end
  local results, words = H.search(ix, text)
  if #results == 0 then
    addHeading(list, tr('Nothing found. Try other words, like "orbs", "rift" or "nivel".'))
    return
  end
  for _, r in ipairs(results) do
    local row = rowOf(r.doc, H.snippet(r.doc, words, l))
    shown[#shown + 1] = row
    addRow(list, row)
  end
end

local function safeDraw(text)
  local ok, err = pcall(draw, text)
  if not ok then g_logger.warning('[helpsearch] ' .. tostring(err)) end
end

local function onSearch(widget, text)
  local hint = window and window:getChildById('searchHint')
  if hint then hint:setVisible(text == '') end
  local later = rawget(_G, 'scheduleEvent')
  if not later then return safeDraw(text) end
  if searchEvent then removeEvent(searchEvent) end
  searchEvent = later(function() searchEvent = nil safeDraw(text) end, 150)
end

-- ---------------------------------------------------------------- public
function show()
  if not alive(window) then return end
  local edit = window:getChildById('searchEdit')
  safeDraw(edit and edit:getText() or '')
  window:show()
  window:raise()
  window:focus()
  if edit then edit:focus() end
end

function hide()
  if alive(window) then window:hide() end
end

function toggle()
  if not alive(window) then return end
  if window:isVisible() then hide() else show() end
end

function search(text)
  if not alive(window) then return end
  local edit = window:getChildById('searchEdit')
  if edit then edit:setText(text or '') end
  safeDraw(text or '')
end

function results() return shown end

-- ---------------------------------------------------------------- module
local function addMenu()
  if menuAdded then return end
  local top = moduleTable('client_chaos_topbar')
  local api = top and top.ChaosTopBar
  if api and api.addEntry then
    local ok, added = pcall(api.addEntry, 'system',
      { text = 'Help Search', icon = 'help', modules = { 'game_helpsearch' }, fns = { 'toggle' }, key = 'Alt+F' })
    menuAdded = ok and added == true
  end
end

local function onGameStart() addMenu() end
local function onGameEnd() hide() end

function init()
  local ok, ui = pcall(g_ui.displayUI, 'helpsearch')
  if not ok or not ui then
    g_logger.warning('[helpsearch] window not loaded: ' .. tostring(ui))
    return
  end
  window = ui
  window:hide()
  local edit = window:getChildById('searchEdit')
  if edit then
    edit.onTextChange = onSearch
    edit.onKeyDown = function(widget, keyCode)
      if keyCode == rawget(_G, 'KeyEscape') then hide() return true end
      if keyCode == rawget(_G, 'KeyEnter') and shown[1] then open(shown[1]) return true end
      return false
    end
  end
  addMenu()
  if rawget(_G, 'connect') and rawget(_G, 'g_game') then
    connect(g_game, { onGameStart = onGameStart, onGameEnd = onGameEnd })
  end
end

function terminate()
  if rawget(_G, 'disconnect') and rawget(_G, 'g_game') then
    disconnect(g_game, { onGameStart = onGameStart, onGameEnd = onGameEnd })
  end
  if searchEvent then removeEvent(searchEvent) end
  searchEvent = nil
  if alive(window) then window:destroy() end
  window, index, shown = nil, nil, {}
end
